const raw = $input.first().json;
const body = raw.body || raw;

const applicationId = String(body.application_id || body.applicationId || '').trim();
const decision = String(body.decision || '').trim();
let interviewDate = String(body.interview_date || body.interviewDate || '').trim();
const interviewTime = String(body.interview_time || body.interviewTime || '').trim();

if (!applicationId) {
  throw new Error('Thiếu application_id.');
}

if (!['Approve', 'Reject'].includes(decision)) {
  throw new Error('Quyết định HR không hợp lệ.');
}

if (decision === 'Approve') {
  // Hỗ trợ cả định dạng DD/MM/YYYY (14/11/2026) và YYYY-MM-DD (2026-11-14)
  const dmyMatch = interviewDate.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (dmyMatch) {
    const [, day, month, year] = dmyMatch;
    interviewDate = `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
  }

  if (!/^\d{4}-\d{2}-\d{2}$/.test(interviewDate)) {
    throw new Error(`Ngày phỏng vấn không hợp lệ: "${interviewDate}"`);
  }

  if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(interviewTime)) {
    throw new Error(`Giờ phỏng vấn không hợp lệ: "${interviewTime}"`);
  }
}

return [{
  json: {
    application_id: applicationId,
    decision,
    interview_date: decision === 'Approve' ? interviewDate : '',
    interview_time: decision === 'Approve' ? interviewTime : ''
  }
}];
